p6+='<hr class="form-divider"><label class="checkline"><input type="checkbox" name="confirm_all_bags" required><span>I have considered all items carried by me, including checked luggage, cabin baggage, personal belongings and any items I am carrying for others. '+req+'</span></label>'

p7='''<div class="form-tip">'''+ic('check-circle')+'''<div><strong>Check carefully before you finish</strong><p>Use Edit to return to any section. Your printed copy will reflect the information on this review screen.</p></div></div><div id="review-content" aria-live="polite"></div><hr class="form-divider">'''+grid(fld('signature_name','Signature — type your full name',ph='Your name as shown in passport',wide=True),fld('signature_date','Declaration date',kind='date',attrs='max="2099-12-31"'),fld('guardian_name','Parent or guardian name (if signing for a child)',ph='Full name',required=False))+'<hr class="form-divider"><label class="checkline"><input type="checkbox" name="confirm_truth" required><span>I confirm that the information in this declaration is true, correct and complete to the best of my knowledge, including information about the goods I am carrying. '+req+'</span></label><div class="important-note">'+ic('info')+'<p>Completing this step prepares a printable declaration copy. <strong>It does not submit your answers to Customs or register an official border declaration.</strong></p></div>'

panes=''.join([pane(1,'About you','Your name, passport and entry information.',p1),pane(2,'Your journey','Tell us how and when you will arrive, and where you will stay.',p2),pane(3,'Where you have been','Tell us about your recent travels, including transit stops.',p3),pane(4,'Customs declarations','Answer each question about goods and belongings you are bringing.',p4),pane(5,'Biosecurity declarations','Answer questions about food, natural items, outdoor equipment and recent activities.',p5),pane(6,'Baggage and final details','Check that all your bags and items are included.',p6),pane(7,'Review and confirm','Read your answers and prepare your printable copy.',p7)])
