declaration_html=f'''<div class="form-head"><div class="container"><div class="form-head-row"><div><div class="crumbs"><a href="index.html">Home</a>{ic('chevron')}<span>Prepare declaration</span></div><div class="eyebrow light">Traveller service</div><h1>Your traveller declaration</h1><p>Answer the questions for one traveller. You can move back to correct information and prepare a copy at the end.</p></div><div class="form-head-note">{ic('lock')} No online transmission</div></div></div></div><div class="container form-layout"><aside class="form-sidebar" aria-label="Declaration progress"><div class="sidebar-title">Your progress <span id="progress-pct" style="float:right">14%</span></div><div class="progress-track"><div class="progress-fill" id="progress-fill"></div></div><nav class="steps-nav" aria-label="Form sections">{sidebar}</nav><div class="sidebar-help"><strong>Need assistance?</strong><p>Read the guidance if you're unsure about items or travel details.</p><a href="help.html" class="text-link">Visit help centre {ic('arrow','icon-sm')}</a></div></aside><div class="form-main"><div class="declaration-tools no-print"><button type="button" id="save-draft" class="tool-button">{ic('save')} Save draft</button><button type="button" id="load-draft" class="tool-button">{ic('upload')} Load saved draft</button><button type="button" id="download-data" class="tool-button">{ic('download')} Download data</button><button type="button" id="import-data" class="tool-button">{ic('upload')} Import data</button><button type="button" id="delete-draft" class="tool-button">{ic('delete')} Delete saved draft</button><input type="file" id="import-file" class="file-input" accept="application/json,.json" aria-label="Import declaration JSON file"></div><div id="status-line" class="status-line" role="status" aria-live="polite">Drafts are saved only when you choose Save draft.</div><div class="form-page-card"><form id="traveller-form" novalidate>{panes}<div class="form-actions"><button id="prev-step" type="button" class="btn btn-outline" hidden>{ic('chevron')} Back</button><span id="step-spacer"></span><div class="form-actions-right"><button id="next-step" type="button" class="btn btn-primary">Continue {ic('arrow')}</button><button id="finish-form" type="button" class="btn btn-primary" hidden>Prepare printable copy {ic('check')}</button></div></div><div id="form-error" class="form-error" role="alert" hidden></div></form><section class="complete-screen" id="complete-screen" aria-live="polite"><span class="complete-mark">{ic('check','icon-xl')}</span><div class="eyebrow">Declaration prepared</div><h2>Your printable copy is ready.</h2><p>You've completed the questions and checked your answers. You can now print the declaration or save it as a PDF using your browser's print options.</p><div class="important-note">{ic('info')}<p><strong>This is a prepared copy, not an official submission.</strong> Your information has not been sent to Customs or any government authority.</p></div><div class="complete-actions"><button type="button" id="print-final" class="btn btn-primary">{ic('printer')} Print / save as PDF</button><button type="button" id="download-final" class="btn btn-outline">{ic('download')} Download data</button><button type="button" id="edit-final" class="btn btn-outline">{ic('edit')} Edit answers</button></div><p class="small">For your privacy, delete your saved draft when it is no longer needed.</p></section><section id="print-sheet" class="print-sheet" aria-label="Printable traveller declaration"></section></div></div></div>'''
(ROOT/'declaration.html').write_text(head('Prepare your declaration','Complete the Square Country Traveller Declaration: passport, travel history, Customs and biosecurity.')+header('declaration.html')+f'<main class="form-page" id="main">{declaration_html}</main>'+footer().replace('</body>','<script defer src="assets/js/declaration.js"></script></body>'),encoding='utf8')

